#!/usr/bin/env node
/**
 * Issue 755/783: writes lib/legal/embedded-policies.ts from the official texts in docs/legal (the source of the texts the
 * legal service serves). The terms and privacy pages show this embedded copy ONLY when the legal service cannot be reached
 * and there is no cached page (lib/legal/embedded.ts). Run it again whenever docs/legal changes; a test fails when the
 * generated file is out of date.
 *
 *   node scripts/embed-legal-policies.mjs          write the file
 *   node scripts/embed-legal-policies.mjs --check  exit 1 when the file is out of date
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCES = [
  { key: "patient_terms", lang: "ar", file: "../docs/legal/01_PATIENT_TERMS.ar.md" },
  { key: "privacy_policy", lang: "ar", file: "../docs/legal/02_PRIVACY_POLICY.ar.md" },
];

export function parsePolicyFile(markdown) {
  const lines = markdown.replace(/\r\n/g, "\n").split("\n");
  let version = "";
  let effective = "";
  const body = [];
  for (const line of lines) {
    const v = /^\*\*الإصدار:\*\*\s*(.+)$/.exec(line.trim());
    const e = /^\*\*تاريخ السريان:\*\*\s*(.+)$/.exec(line.trim());
    if (v) version = v[1].trim();
    else if (e) effective = e[1].trim();
    else if (/^#\s+/.test(line) && body.length === 0) continue; // the page already has this title
    else body.push(line);
  }
  const draft = /مسودة/.test(version);
  const date = /^\d{4}-\d{2}-\d{2}$/.test(effective) ? effective : null;
  return { version: version.replace(/\s*\(مسودة\)\s*/, "").trim(), effective_date: date, draft, content: body.join("\n").trim() + "\n" };
}

export function render() {
  const entries = SOURCES.map(({ key, lang, file }) => {
    const parsed = parsePolicyFile(readFileSync(resolve(root, file), "utf8"));
    return `  ${key}: {\n    ${lang}: ${JSON.stringify(parsed, null, 2).replace(/\n/g, "\n    ")},\n  },`;
  });
  return `// GENERATED by scripts/embed-legal-policies.mjs from docs/legal. Do not edit by hand.\nexport type EmbeddedPolicy = { version: string; effective_date: string | null; draft: boolean; content: string };\nexport const EMBEDDED_POLICIES: Record<"patient_terms" | "privacy_policy", Partial<Record<"ar" | "en", EmbeddedPolicy>>> = {\n${entries.join("\n")}\n};\n`;
}

const target = resolve(root, "lib/legal/embedded-policies.ts");
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const next = render();
  if (process.argv.includes("--check")) {
    let current = "";
    try { current = readFileSync(target, "utf8"); } catch { /* missing */ }
    if (current !== next) { console.error("lib/legal/embedded-policies.ts is out of date: run node scripts/embed-legal-policies.mjs"); process.exit(1); }
  } else {
    writeFileSync(target, next);
    console.log("wrote lib/legal/embedded-policies.ts");
  }
}
